-- 539: Original BrillaPrep WASSCE Core Mathematics sprint 3 beta questions, part 1 of 10 (batch wassce-core-math-sprint3-001).
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_539_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_539_guard;
INSERT INTO _migration_539_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wcms3_001' AND NOT (q.topic_id IS 'topic_wassce_p2_math_alg' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Simplify 4a + 2b − a + 5b.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 3a + 7b","B. 3a + 3b","C. 5a + 7b","D. 9ab"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Collect the a-terms: 4a − a = 3a. Collect the b-terms: 2b + 5b = 7b. Hence 4a + 2b − a + 5b = 3a + 7b. (9ab wrongly multiplies unlike terms together; 3a + 3b mis-adds the b-terms.) Therefore the correct answer is A: 3a + 7b.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Simplify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wcms3_001' AND NOT (r.batch_id IS 'wassce-core-math-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_539_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wcms3_002' AND NOT (q.topic_id IS 'topic_wassce_p2_math_alg' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Solve the equation 5x − 3 = 17.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. x = 20","B. x = 4","C. x = 14/5","D. x = 3"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Add 3 to both sides: 5x = 20. Divide both sides by 5: x = 4. Check: 5(4) − 3 = 20 − 3 = 17, as required. (x = 20 forgets the final division; x = 14/5 subtracts 3 instead of adding.) Therefore the correct answer is B: x = 4.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Solve' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wcms3_002' AND NOT (r.batch_id IS 'wassce-core-math-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_539_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wcms3_003' AND NOT (q.topic_id IS 'topic_wassce_p2_math_alg' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Expand the expression 2(3y − 5).' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 6y − 5","B. 3y − 10","C. 6y − 10","D. 6y + 10"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Multiply each term inside the bracket by 2: 2 × 3y = 6y and 2 × (−5) = −10, giving 6y − 10. (6y − 5 multiplies only the first term by 2.) Therefore the correct answer is C: 6y − 10.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Expand' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wcms3_003' AND NOT (r.batch_id IS 'wassce-core-math-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_539_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wcms3_004' AND NOT (q.topic_id IS 'topic_wassce_p2_math_alg' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Given that p = 3q + 2, find the value of p when q = 4.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 24","B. 12","C. 9","D. 14"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Substitute q = 4 into the formula: p = 3(4) + 2 = 12 + 2 = 14. (24 comes from wrongly computing 3 × (4 + 2); 12 forgets to add 2.) Therefore the correct answer is D: 14.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Evaluate' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wcms3_004' AND NOT (r.batch_id IS 'wassce-core-math-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_539_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wcms3_005' AND NOT (q.topic_id IS 'topic_wassce_p2_math_alg' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Solve the equation 4(x + 3) = 2x + 18.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. x = 3","B. x = 6","C. x = 15","D. x = 30"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Expand the bracket: 4x + 12 = 2x + 18. Subtract 2x from both sides: 2x + 12 = 18. Subtract 12: 2x = 6, so x = 3. Check: 4(3 + 3) = 24 and 2(3) + 18 = 24, as required. (x = 6 stops after finding 2x.) Therefore the correct answer is A: x = 3.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Solve' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wcms3_005' AND NOT (r.batch_id IS 'wassce-core-math-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_wcms3_001', 'topic_wassce_p2_math_alg', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'Simplify 4a + 2b − a + 5b.', 'multiple_choice', NULL, '["A. 3a + 7b","B. 3a + 3b","C. 5a + 7b","D. 9ab"]', 'A', 'Collect the a-terms: 4a − a = 3a. Collect the b-terms: 2b + 5b = 7b. Hence 4a + 2b − a + 5b = 3a + 7b. (9ab wrongly multiplies unlike terms together; 3a + 3b mis-adds the b-terms.) Therefore the correct answer is A: 3a + 7b.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Simplify', 'AO1', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_wcms3_002', 'topic_wassce_p2_math_alg', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'Solve the equation 5x − 3 = 17.', 'multiple_choice', NULL, '["A. x = 20","B. x = 4","C. x = 14/5","D. x = 3"]', 'B', 'Add 3 to both sides: 5x = 20. Divide both sides by 5: x = 4. Check: 5(4) − 3 = 20 − 3 = 17, as required. (x = 20 forgets the final division; x = 14/5 subtracts 3 instead of adding.) Therefore the correct answer is B: x = 4.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Solve', 'AO1', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_wcms3_003', 'topic_wassce_p2_math_alg', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'Expand the expression 2(3y − 5).', 'multiple_choice', NULL, '["A. 6y − 5","B. 3y − 10","C. 6y − 10","D. 6y + 10"]', 'C', 'Multiply each term inside the bracket by 2: 2 × 3y = 6y and 2 × (−5) = −10, giving 6y − 10. (6y − 5 multiplies only the first term by 2.) Therefore the correct answer is C: 6y − 10.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Expand', 'AO1', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_wcms3_004', 'topic_wassce_p2_math_alg', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'Given that p = 3q + 2, find the value of p when q = 4.', 'multiple_choice', NULL, '["A. 24","B. 12","C. 9","D. 14"]', 'D', 'Substitute q = 4 into the formula: p = 3(4) + 2 = 12 + 2 = 14. (24 comes from wrongly computing 3 × (4 + 2); 12 forgets to add 2.) Therefore the correct answer is D: 14.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Evaluate', 'AO1', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_wcms3_005', 'topic_wassce_p2_math_alg', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'Solve the equation 4(x + 3) = 2x + 18.', 'multiple_choice', NULL, '["A. x = 3","B. x = 6","C. x = 15","D. x = 30"]', 'A', 'Expand the bracket: 4x + 12 = 2x + 18. Subtract 2x from both sides: 2x + 12 = 18. Subtract 12: 2x = 6, so x = 3. Check: 4(3 + 3) = 24 and 2(3) + 18 = 24, as required. (x = 6 stops after finding 2x.) Therefore the correct answer is A: x = 3.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Solve', 'AO2', NULL, NULL, 'board_waec');
